sys_script_include.script:
var UserAlreadyRegistered = Class.create();
UserAlreadyRegistered.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    isUserAlreadyRegistered: function(user, training_date) {
        var gr = new GlideRecord('x_873666_simplic_0_training_registration');
        gr.addQuery('user', user);
        gr.addQuery('training_date', training_date);
        gr.query();
        return gr.hasNext();
    }
});
